const company = $input.first().json.company_name;

const prefix = company
  .replace(/[^A-Za-z]/g, "")
  .toUpperCase()
  .substring(0, 3);

const random = Math.floor(1000 + Math.random() * 9000);

return [{
  json: {
    ...$input.first().json,
    client_id: `${prefix}-${random}`
  }
}];

parameters.text:
You are an experienced Operations Manager responsible for reviewing newly signed clients before they enter the company's onboarding process.

Your job is to analyze the client information and provide an operational assessment that will help the Sales, Operations, Finance, and IT departments prepare for onboarding.

Client Information

Company Name: {{ $json.company_name }}

Contact Name: {{ $json.contact_name }}

Email: {{ $json.email }}

Industry: {{ $json.industry }}

Requested Service: {{ $json.service }}

Client Type: {{ $json.client_type }}

Instructions:

- Assess the business risk of onboarding this client.
- Estimate the onboarding complexity.
- Identify any missing information that may delay onboarding.
- Recommend the next operational steps.
- Determine the onboarding priority.

Return ONLY valid JSON matching the required schema.

Do not include markdown.
Do not include explanations.
Do not wrap the JSON in code fences.

parameters.jsCode:
const managers = {
  Manufacturing: "John Santos",
  FinTech: "Sarah Lee",
  Healthcare: "Michael Cruz",
  Logistics: "John Santos",
  Technology: "Alex Johnson"
};

const industry = $json.fields["Industry"];

return [{
  json: {
    ...$json,
    account_manager: managers[industry] || "Unassigned"
  }
}];

const timeline = [
  {
    day: 1,
    task: "Kickoff Meeting"
  },
  {
    day: 2,
    task: "Requirements Gathering"
  },
  {
    day: 4,
    task: "Solution Design"
  },
  {
    day: 7,
    task: "Workflow Development"
  },
  {
    day: 10,
    task: "Client Review"
  }
];

return [{
  json: {
    ...$json,
    deal_timeline: timeline
  }
}];

const checklist = [
  {
    task: "Send welcome email",
    status: "Pending"
  },
  {
    task: "Schedule kickoff meeting",
    status: "Pending"
  },
  {
    task: "Collect required documents",
    status: "Pending"
  },
  {
    task: "Set up client workspace",
    status: "Pending"
  },
  {
    task: "Begin implementation",
    status: "Pending"
  }
];

return [{
  json: {
    ...$json,
    onboarding_checklist: checklist
  }
}];

